  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cellFine=Math.tanh((Math.sin(sx*0.25+t*0.3)*Math.sin(sy*0.22-t*0.4)+Math.sin((sx-sy)*0.18+t*0.7)*0.4)*1.2)*0.15;
  const reaction1=Math.tanh((act1-inh1*0.7+bg*0.3+spiral1+spiral2)*2.2);
  const reaction2=Math.tanh((act2-inh2*0.6+cellFine+spiral2)*2.5);
  const reaction=reaction1*0.7+reaction2*0.3;
  const blend=reaction*0.7+(cell+cellFine)*0.3;
